import java.net.URL;

public class ClassX {
    /**
     * Fetches content from a generated URL after validating the host.
     * 
     * This function sanitizes the host by checking for invalid characters like spaces.
     */
    public static String fetchContent(String host) {
        String sanitizedHost = host.replaceAll("[^a-zA-Z0-9]", "");
        try {
            URL url = new URL("http://" + sanitizedHost);
            return url.getContent().toString();
        } catch (Exception e) {
            return "Error: " + e.getMessage();
        }
    }
}
