import com.github.javaparser.ast.type.Type;

/**
 * Represents an instance of an expression.
 * 
 * @author 
 * @version 0.9.10
 */
public class InstanceOfExpr extends Expression {

	private Type type;
	private Expression expr;

	public InstanceOfExpr(Type type, Expression expr) {
		this.type = type;
		this.expr = expr;
	}

	public Type getType() {
		return type;
	}

	public void setType(Type type) {
		this.type = type;
	}

	public Expression getExpr() {
		return expr;
	}

	public void setExpr(Expression expr) {
		this.expr = expr;
	}

	@Override
	public NodeList<Node> getChildNodes() {
		return new NodeList<Node>(expr, type);
	}

	@Override
	public String toString() {
		return "instanceof " + expr + " instanceof " + type;
	}

	@Override
	public boolean isInstanceOf(ClassOrInterfaceType type) {
		return type.isInstance(this.type);
	}
}
