		this.autowire = autowire;
	}

	public SpringModule(ApplicationContext context) {
		this(context, false);
	}

	public <T> T get(Class<T> type) {
		return (T) context.getBean(type);
	}

	public <T> T get(Class<T> type, String name) {
		return (T) context.getBean(name);
	}

	public void register(Object instance) {
		singletons.put(instance.getClass(), instance);
	}

	public Container buildContainer() {
		AutowireCapableBeanFactory factory = context.getAutowireCapableBeanFactory();
		ProviderFactory providerFactory = new ProviderFactoryImpl(factory, autowire);
		InterceptorStack interceptorStack = new InterceptorStack();
		interceptorStack.add(new SpringInterceptor(context));
		return new ContainerImpl(context, singletons, providerFactory, interceptorStack);

