package com.github.josepablocasas.app.security.jwt;

import java.util.Date;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import com.github.josepablocasas.app.security.jwt.model.UserToken;
import com.github.josepablocasas.app.security.jwt.repository.UserTokenRepository;

@Service
public class TokenService {

	@Autowired
	private UserTokenRepository tokenRepository;

	public UserToken createToken(String username) {
		UserToken token = new UserToken();
		token.setUsername(username);
		token.setToken(TokenUtils.generateToken(username));
		token.setExpirationDate(new Date(System.currentTimeMillis() + TokenUtils.TOKEN_EXPIRATION_TIME));
		return tokenRepository.save(token);
	}

	public UserToken findByToken(String token) {
		return tokenRepository.findByToken(token);
	}
}
