public class FileUtil {

    public static void writeToFile(String file, String content) throws IOException {
        File f = new File(file);
        if (!f.exists()) {
            f.createNewFile();
        }
        try (OutputStream os = new FileOutputStream(f)) {
            os.write(content.getBytes());
        }
