		this.issuer = issuer;
		this.audience = audience;
		this.claims = claims;
		this.expiration = expiration;
		this.token = generateToken();
		this.issuedAt = new Date();
		this.expiresAt = new Date(issuedAt.getTime() + expiration);
	}

	public static Token parseToken(String token, String secret) throws InvalidTokenException {
		Algorithm algorithm = Algorithm.HMAC256(secret);
		JWTVerifier verifier = JWT.require(algorithm).withIssuer("http://localhost:8080/").build();
		DecodedJWT decodedJWT = verifier.verify(token);
		return new Token(secret, decodedJWT.getIssuer(), decodedJWT.getAudience(), decodedJWT.getClaims(),
