 */
public class TheDescent {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int surfaceN = in.nextInt(); // the number of points used to draw the surface of Mars.
        int[] h = new int[surfaceN]; // the h of each point
        for (int i = 0; i < surfaceN; i++) {
            h[i] = in.nextInt(); // represents the height of each point
        }

        int currentHeight = 0;
        int currentPosition = 0;
        int currentJump = 0;
        for (int i = 0; i < surfaceN; i++) {
            if (h[i] > currentHeight) {
                currentHeight = h[i];
                currentPosition = i;
            }
            if (h[i] < currentHeight) {
                currentJump++;
            }
        }
        System.out.println(currentPosition + " " + currentJump);
    }

}
