package com.github.lukaszlenart.code_assistant.util;

import java.io.File;
import java.io.IOException;
import java.nio.charset.Charset;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

public class FileUtils {

    public static String readFileAsString(String file) throws IOException {
        return readFileAsString(new File(file));
    }

    public static String readFileAsString(File file) throws IOException {
        return new String(Files.readAllBytes(Paths.get(file.toURI())), Charset.forName("UTF-8"));
    }

    public static List<String> readFileAsLines(String file) throws IOException {
        return readFileAsLines(new File(file));
    }

    public static List<String> readFileAsLines(File file) throws IOException {
        List<String> lines = new ArrayList<>();
        Files.lines(Paths.get(file.toURI())).forEach(lines::add);
        return lines;
    }

    public static void writeFile(String file, String content) throws IOException {
        writeFile(new File(file), content);
    }

    public static void writeFile(File file, String content) throws IOException {
        Files.write(Paths.get(file.toURI()), content.getBytes(Charset.forName("UTF-8")));
    }
}
