import com.github.wolfie.quester.ast.Node;
import com.github.wolfie.quester.ast.parser.Parser;
import com.github.wolfie.quester.ast.visitors.CheckVisitor;
import com.github.wolfie.quester.ast.visitors.GenerateVisitor;
import com.github.wolfie.quester.ast.visitors.PrintVisitor;
import com.github.wolfie.quester.ast.visitors.TransformVisitor;

public class Quest {
    public static void main(String[] args) throws IOException {
        if (args.length!= 3) {
            System.out.println("Usage: java -jar quester.jar <input> <output> <language>");
            System.exit(1);
        }

        Path input = Paths.get(args[0]);
        Path output = Paths.get(args[1]);
        String language = args[2];

        List<Node> ast = Parser.parse(Files.readAllLines(input));

        CheckVisitor checkVisitor = new CheckVisitor();
        ast = checkVisitor.visit(ast);

        TransformVisitor transformVisitor = new TransformVisitor();
        ast = transformVisitor.visit(ast);

        GenerateVisitor generateVisitor = new GenerateVisitor();
        generateVisitor.setLanguage(language);
        Map<String, String> generated = generateVisitor.visit(ast);

        PrintVisitor printVisitor = new PrintVisitor();
        printVisitor.visit(generated);

        Files.write(output, generated.values());
    }
}
