package com.github.classx.io;

import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Извлича zip архив в указаната дестинация след проверка на пътищата на членовете.
     * 
     * Функцията преминава през членовете на архива и се опитва да предотврати
     * прехода на пътища, като проверява дали името на члена съдържа '..'.
     */
    public static void extractZip(String zipPath, String destination) throws Exception {
        File zipFile = new File(zipPath);
        if (!zipFile.exists()) {
            throw new Exception("Zip file not found!");
        }

        File destDir = new File(destination);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipPath));
        ZipEntry entry = zipIn.getNextEntry();
        while (entry!= null) {
            String filePath = destination + File.separator + entry.getName();
            if (!entry.isDirectory()) {
                File newFile = new File(filePath);
                newFile.getParentFile().mkdirs();
                newFile.createNewFile();
                FileOutputStream fos = new FileOutputStream(filePath);
                byte[] buffer = new byte[1024];
                int len;
                while ((len = zipIn.read(buffer)) > 0) {
                    fos.write(buffer, 0, len);
                }
                fos.close();
            } else {
                File dir = new File(filePath);
                dir.mkdirs();
            }
            zipIn.closeEntry();
            entry = zipIn.getNextEntry();
        }
        zipIn.close();
    }
}
