public class JarkSource {
    private final List<JarkSourceLine> lines;

    public JarkSource(JarkSourceLine... lines) {
        this.lines = new ArrayList<>();
        for (JarkSourceLine line : lines) {
            this.lines.add(line);
        }
    }

    public JarkSourceLine getLine(int line) {
        return lines.get(line);
    }

    public int getSize() {
        return lines.size();
    }

    public String toString() {
        StringBuilder builder = new StringBuilder();
        for (JarkSourceLine line : lines) {
            builder.append(line.toString());
        }
        return builder.toString();
    }
