    /**
     * 提取一个 zip 压缩档案到指定的目的地，并在此过程中检查成员路径。
     * 
     * 该函数遍历压缩档案中的成员，并尝试通过检查成员名称是否包含 '..' 来防止路径遍历。
     */
    public static void extractZip(File zipFile, File destDir) {
        FileInputStream fis = null;
        ZipInputStream zis = null;
        try {
            fis = new FileInputStream(zipFile);
            zis = new ZipInputStream(fis);
            ZipEntry ze = null;
            while ((ze = zis.getNextEntry())!= null) {
                String entryName = ze.getName();
                if (entryName.contains("..")) {
                    System.out.println("Invalid entry name: " + entryName);
                    continue;
                }
                File entryDest = new File(destDir, entryName);
                if (ze.isDirectory()) {
                    entryDest.mkdirs();
                    continue;
                }
                FileOutputStream fos = new FileOutputStream(entryDest);
                byte[] buf = new byte[1024];
                int len = 0;
                while ((len = zis.read(buf))!= -1) {
                    fos.write(buf, 0, len);
                }
                fos.close();
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                if (fis!= null) {
                    fis.close();
                }
                if (zis!= null) {
                    zis.close();
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}
