package nl.tudelft.controller;

import java.util.List;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;

import nl.tudelft.model.Test;
import nl.tudelft.model.User;
import nl.tudelft.repository.TestRepository;
import nl.tudelft.repository.UserRepository;

@Controller
@RequestMapping("/test")
public class TestController {

	@Autowired
	private TestRepository testRepository;

	@Autowired
	private UserRepository userRepository;

	@GetMapping
	public String getTestList(Model model) {
		List<Test> tests = testRepository.findAll();
		model.addAttribute("tests", tests);
		return "test/list";
	}

	@GetMapping("/create")
	public String createTest(Model model) {
		model.addAttribute("test", new Test());
		model.addAttribute("users", userRepository.findAll());
		return "test/create";
	}

	@PostMapping("/create")
	public String createTest(@ModelAttribute Test test) {
		testRepository.save(test);
		return "redirect:/test";
	}

	@GetMapping("/delete")
	public String deleteTest(@RequestParam Long id) {
		testRepository.deleteById(id);
		return "redirect:/test";
	}

}
