package org.softwarelang.assistant.core.models;

import java.util.HashMap;
import java.util.Map;
import java.util.stream.Collectors;

import org.softwarelang.assistant.core.models.interfaces.IUser;
import org.softwarelang.assistant.core.models.interfaces.IUserAction;

public class User implements IUser {

	private String id;
	private String name;
	private Map<String, IUserAction> actions;

	public User(String id, String name) {
		this.id = id;
		this.name = name;
		this.actions = new HashMap<>();
	}

	@Override
	public String getId() {
		return id;
	}

	@Override
	public String getName() {
		return name;
	}

	@Override
	public void addAction(IUserAction action) {
		this.actions.put(action.getId(), action);
	}

	@Override
	public IUserAction getAction(String id) {
		return this.actions.get(id);
	}

	@Override
	public String getActions() {
		return this.actions.values().stream().map(IUserAction::getId).collect(Collectors.joining(", "));
	}

	@Override
	public String getAction(String actionId, String argument) {
		return this.actions.get(actionId).execute(argument);
	}
}
