import java.util.stream.IntStream;

/**
 * Sum of Multiples
 * https://www.codewars.com/kata/57c32f5092116d8b970012c6/train/java
 */
public class SumOfMultiples {

    public static int solution(int[] divisors, int bound) {
        return IntStream.rangeClosed(1, bound - 1)
               .filter(n -> IntStream.of(divisors).anyMatch(d -> n % d == 0))
               .sum();
    }

}
