package com.github.misterpeanut.codewars.kyu6;

import java.util.HashMap;
import java.util.Map;

public class RomanNumeralsHelper {
    private static final Map<Integer, String> ROMAN_NUMERALS = new HashMap<>();

    static {
        ROMAN_NUMERALS.put(1, "I");
        ROMAN_NUMERALS.put(4, "IV");
        ROMAN_NUMERALS.put(5, "V");
        ROMAN_NUMERALS.put(9, "IX");
        ROMAN_NUMERALS.put(10, "X");
        ROMAN_NUMERALS.put(40, "XL");
        ROMAN_NUMERALS.put(50, "L");
        ROMAN_NUMERALS.put(90, "XC");
        ROMAN_NUMERALS.put(100, "C");
        ROMAN_NUMERALS.put(400, "CD");
        ROMAN_NUMERALS.put(500, "D");
        ROMAN_NUMERALS.put(900, "CM");
        ROMAN_NUMERALS.put(1000, "M");
    }

    public static String solution(int n) {
        if (n < 1 || n > 3999) {
            return null;
        }
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<Integer, String> entry : ROMAN_NUMERALS.entrySet()) {
            int key = entry.getKey();
            String value = entry.getValue();
            while (n >= key) {
                sb.append(value);
                n -= key;
            }
        }
        return sb.toString();
    }
}
