/**
 * 11. Feladat. Írj egy programot, ami egy 100 elemű, 0 és 100 közötti véletlen számokat tartalmazó tömböt generál.
 * Egy másik programban számítsd ki a tömbben előforduló 0 és 1 közötti számok számát.
 */
public class Exercise11 {

    public static void main(String[] args) {
        int[] numbers = new int[100];
        Random random = new Random();
        for (int i = 0; i < numbers.length; i++) {
            numbers[i] = random.nextInt(101);
        }
        int count = 0;
        for (int i = 0; i < numbers.length; i++) {
            if (numbers[i] == 0 || numbers[i] == 1) {
                count++;
            }
        }
        System.out.println("A tömbben " + count + " db 0 és 1 közötti szám van.");
    }

}
