package it.polito.tdp.porto.db;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;

import it.polito.tdp.porto.model.Porto;

public class PortoDAO {

	public List<Porto> listAllPorti() {
		String sql = "SELECT * FROM porto";
		List<Porto> result = new ArrayList<Porto>();
		try {
			Connection conn = DBConnect.getConnection();
			PreparedStatement st = conn.prepareStatement(sql);
			ResultSet res = st.executeQuery();
			while (res.next()) {
				Porto p = new Porto(res.getInt("id"), res.getString("nome"), res.getString("citta"));
				result.add(p);
			}
			conn.close();
			return result;
		} catch (SQLException e) {
			// TODO Auto-generated catch block
			e.printStackTrace();
			return null;
		}
	}

}
