public static String extract(String archive, String member) throws Exception {
    if (member.startsWith("/")) {
        throw new Exception("Invalid member name");
    }
    File file = new File(archive);
    if (!file.exists()) {
        throw new Exception("Invalid archive name");
    }
    if (!file.isFile()) {
        throw new Exception("Archive must be a file");
    }
