package il.co.ilrd.ds.bst;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.function.Predicate;

public class BST<T extends Comparable<T>> implements Iterable<T> {
    private BSTNode<T> root;
    private int size;

    public BST() {
        root = null;
        size = 0;
    }

    public BST(Collection<T> collection) {
        this();
        for (T element : collection) {
            add(element);
        }
    }

    public BST(BST<T> other) {
        this();
        addAll(other);
    }

    public BST(Comparator<T> comparator) {
        this();
        root = new BSTNode<>(null, null, null, comparator);
        size = 0;
    }

    public BST(T[] array, Comparator<T> comparator) {
        this(comparator);
        for (T element : array) {
            add(element);
        }
    }

    public BST(T[] array) {
        this(array, null);
    }

    public BST(Comparator<T> comparator, T[] array) {
        this(comparator);
