package com.github.p4535992.exercism.java.exercises.anagram;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Anagram {

    private final String source;

    public Anagram(String source) {
        this.source = source;
    }

    public List<String> match(List<String> candidates) {
        List<String> result = new ArrayList<>();
        for (String candidate : candidates) {
            if (candidate.equals(source)) {
                continue;
            }
            if (isAnagram(source, candidate)) {
                result.add(candidate);
            }
        }
        return result;
    }

    private boolean isAnagram(String source, String candidate) {
        char[] sourceChars = source.toCharArray();
        Arrays.sort(sourceChars);
        char[] candidateChars = candidate.toCharArray();
        Arrays.sort(candidateChars);
        return Arrays.equals(sourceChars, candidateChars);
    }
}
