package com.github.kabirbaidhya.java.interview.questions.java.basics;

import java.util.Arrays;

/**
 * Given an array of numbers, find the missing number in the array.
 * For example,
 * <p>
 * Input: [1,2,3,4,6,7,8]
 * Output: 5
 * <p>
 * Input: [1,2,3,4,5]
 * Output: 6
 * <p>
 * Input: [1,2,3,4,5,7,8]
 * Output: 6
 * <p>
 * Input: [1,2,3,4,6,7,8]
 * Output: 5
 */
public class FindTheMissingNumber {
    public static void main(String[] args) {
        System.out.println(findMissingNumber(new int[]{1, 2, 3, 4, 6, 7, 8}));
        System.out.println(findMissingNumber(new int[]{1, 2, 3, 4, 5}));
        System.out.println(findMissingNumber(new int[]{1, 2, 3, 4, 5, 7, 8}));
        System.out.println(findMissingNumber(new int[]{1, 2, 3, 4, 6, 7, 8}));
    }

    private static int findMissingNumber(int[] arr) {
        Arrays.sort(arr);
        int missingNumber = 0;
        for (int i = 1; i <= arr.length; i++) {
            if (arr[i - 1]!= i) {
                missingNumber = i;
                break;
            }
        }
        return missingNumber;
    }
}
