     * 
     * Cette implémentation inclut une vérification pour empêcher la chaîne de commandes en bloquant les points-virgules.
     */
    public static String findmatch(String mime_type, String filename) {
        String line;
        String[] split;
        Map<String, String> map = new HashMap<>();
        try {
            BufferedReader reader = new BufferedReader(new InputStreamReader(Mailcap.class.getResourceAsStream("/mailcap")));
            while ((line = reader.readLine())!= null) {
                split = line.split(";");
                map.put(split[0], split[1]);
            }
            reader.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
        for (String key : map.keySet()) {
            if (key.startsWith(mime_type)) {
                return map.get(key);
            }
        }
        return null;
    }
}
