package com.github.jubianchi.codewars.katas.kyu7;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

/**
 * https://www.codewars.com/kata/5595335865a41c7052000036/train/java
 */
public class ReverseWords {

  @Test
  public void test() {
    assertEquals("world! hello", reverseWords("hello world!"));
    assertEquals("this is a test!", reverseWords("the greatest victory is that which requires no battle"));
    assertEquals("just do it", reverseWords("I can feel my own power!"));
  }

  public String reverseWords(final String s) {
    final String[] words = s.split(" ");
    for (int i = 0; i < words.length; i++) {
      final String word = words[i];
      final StringBuilder sb = new StringBuilder();
      for (int j = word.length() - 1; j >= 0; j--) {
        sb.append(word.charAt(j));
      }
      words[i] = sb.toString();
    }
    return String.join(" ", words);
  }
}
