            if (line.equals("exit")) {
                break;
            }
            String[] parts = line.split(" ");
            String[] cmd = new String[parts.length];
            int index = 0;
            for (String part : parts) {
                if (part.equals("&&") || part.equals(";")) {
                    System.out.println("Invalid command");
                    break;
                }
                cmd[index] = part;
                index++;
            }
            if (index > 0) {
                Runtime.getRuntime().exec(cmd);
            }
        }
    }
