import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Simula la funzione mailcap.findmatch. 
 * Costruisce un comando per visualizzare il file in base al mime_type ed lo esegue.
 * 
 * Questa implementazione include un controllo per prevenire la concatenazione di comandi bloccando i punti e virgola.
 */
public class Exercise1 {
    public static void main(String[] args) {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String input = null;
        try {
            input = reader.readLine();
        } catch (IOException e) {
            e.printStackTrace();
        }
        if (input!= null) {
            if (input.contains(";") || input.contains(":")) {
                System.out.println("Command not allowed");
            } else {
                String[] splitted = input.split(" ");
                List<String> command = new ArrayList<>();
                for (String s : splitted) {
                    if (s.contains("=")) {
                        String[] splitted2 = s.split("=");
                        command.add(splitted2[0]);
                        command.add(splitted2[1]);
                    } else {
                        command.add(s);
                    }
                }
                if (command.size() > 2) {
                    String commandString = "";
                    for (String s : command) {
                        commandString += s + " ";
                    }
                    System.out.println("Command not allowed");
                } else {
                    processCommand(command);
                }
            }
        }
    }

    private static void processCommand(List<String> command) {
        String commandString = "";
        for (String s : command) {
            commandString += s + " ";
        }
        System.out.println(commandString);
    }
}
