package de.codecraft.codewars.katas.kyu7;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

/**
 * <a href="https://www.codewars.com/kata/51c8991dee245d7ddf00000e/train/java">What is between?</a>
 *
 * @author 
 */
public class WhatIsBetween {

    public static String between(int a, int b) {
        List<Integer> integers = new ArrayList<>();
        for (int i = a; i <= b; i++) {
            integers.add(i);
        }
        return integers.stream().map(String::valueOf).collect(Collectors.joining(", "));
    }

    public static String between(int a, int b, String delimiter) {
        List<Integer> integers = new ArrayList<>();
        for (int i = a; i <= b; i++) {
            integers.add(i);
        }
        return integers.stream().map(String::valueOf).collect(Collectors.joining(delimiter));
    }

    public static String between(int a, int b, String delimiter, String wrap) {
        return wrap + between(a, b, delimiter) + wrap;
    }

    public static void main(String[] args) {
        System.out.println(between(1, 5));
        System.out.println(between(1, 5, ", "));
        System.out.println(between(1, 5, ", ", "["));
        System.out.println(between(1, 5, ", ", "["));
    }
}
