     */
    List<String> getArguments();

    /**
     * Geeft de argumenten van het commando als een String.
     * 
     * @return De argumenten van het commando als een String.
     */
    String getArgumentsAsString();

    /**
     * Geeft de argumenten van het commando als een String.
     * 
     * @return De argumenten van het commando als een String.
     */
    default String getArgumentsAsListAsString() {
        StringBuilder builder = new StringBuilder();
        for (String arg : getArguments()) {
            builder.append(arg).append(" ");
        }
        return builder.toString().trim();
    }

    /**
     * Geeft de argumenten van het commando als een List van Strings.
     * 
     * @return De argumenten van het commando als een List van Strings.
     */
    default List<String> getArgumentsAsList() {
        List<String> args = new ArrayList<>();
        for (String arg : getArguments()) {
            args.add(arg);
        }
        return args;
    }

