package nl.tudelft.contextproject.controller;

import nl.tudelft.contextproject.model.Test;
import nl.tudelft.contextproject.model.User;
import nl.tudelft.contextproject.service.TestService;
import nl.tudelft.contextproject.service.UserService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;

import java.util.List;

@Controller
@RequestMapping("/test")
public class TestController {
    @Autowired
    private TestService testService;

    @Autowired
    private UserService userService;

    @GetMapping("/{testId}")
    public String showTest(@PathVariable("testId") Long testId, Model model) {
        Test test = testService.getTest(testId);
        model.addAttribute("test", test);
        return "test";
    }

    @GetMapping("/{testId}/start")
    public String startTest(@PathVariable("testId") Long testId, Model model) {
        Test test = testService.getTest(testId);
        List<User> users = userService.getAllUsers();
        model.addAttribute("test", test);
        model.addAttribute("users", users);
        return "test-start";
    }

    @PostMapping("/{testId}/start")
    public String startTest(@PathVariable("testId") Long testId, Model model, Long userId) {
        Test test = testService.getTest(testId);
        User user = userService.getUser(userId);
        testService.startTest(test, user);
        return "redirect:/test/" + testId;
    }
}
