package de.dhbw.jass.model;

/**
 * Ein Codeblock ist ein Code-Snippet, welches in der Lösung des Codeblocks-Aufgabenblattes verwendet werden kann.
 */
public class Codeblock {
    /**
     * Der Code, welcher im Codeblock-Aufgabenblatt verwendet wird.
     */
    private String code;

    /**
     * Der Name des Codeblocks.
     */
    private String name;

    /**
     * Der Codeblock-Aufgabenblatt, in dem dieser Codeblock verwendet wird.
     */
    private CodeblockTask task;

    /**
     * Erstellt einen neuen Codeblock.
     * 
     * @param name Der Name des Codeblocks.
     * @param code Der Code, welcher im Codeblock-Aufgabenblatt verwendet wird.
     * @param task Der Codeblock-Aufgabenblatt, in dem dieser Codeblock verwendet wird.
     */
    public Codeblock(String name, String code, CodeblockTask task) {
        this.name = name;
        this.code = code;
        this.task = task;
    }

    /**
     * Gibt den Code zurück.
     * 
     * @return Der Code, welcher im Codeblock-Aufgabenblatt verwendet wird.
     */
    public String getCode() {
        return code;
    }

    /**
     * Gibt den Namen des Codeblocks zurück.
     * 
     * @return Der Name des Codeblocks.
     */
    public String getName() {
        return name;
    }

    /**
     * Gibt den Codeblock-Aufgabenblatt zurück, in dem dieser Codeblock verwendet wird.
     * 
     * @return Der Codeblock-Aufgabenblatt, in dem dieser Codeblock verwendet wird.
     */
    public CodeblockTask getTask() {
        return task;
    }

    /**
     * Gibt den Codeblock zurück.
     * 
     * @return Der Codeblock.
     */
    @Override
    public String toString() {
        return code;
    }
}
