package fi.helsinki.cs.tmc.assistant;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.net.Socket;

/**
 * This class is responsible for communication with the assistant server.
 */
public class Assistant {

    private Socket socket;
    private BufferedReader in;
    private PrintWriter out;

    /**
     * Connects to the assistant server.
     */
    public Assistant() {
        try {
            socket = new Socket("localhost", 4321);
            in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            out = new PrintWriter(socket.getOutputStream(), true);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    /**
     * Sends a message to the assistant server.
     *
     * @param message the message to send
     */
    public void send(String message) {
        out.println(message);
    }

    /**
     * Reads a response from the assistant server.
     *
     * @return the response from the assistant server
     */
    public String read() {
        try {
            return in.readLine();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    /**
     * Closes the connection to the assistant server.
     */
    public void close() {
        try {
            socket.close();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
