public class PiratesOfTheCaribbean {

	public static String[] findCaptain(String[] ships) {
		return Arrays.stream(ships)
				.filter(s -> s.contains("Captain"))
				.map(s -> s.substring(0, s.indexOf("Captain")))
				.toArray(String[]::new);
	}

	public static String[] findCaptain(String[] ships) {
		Map<String, String> map = new HashMap<>();
		for (String ship : ships) {
			String[] split = ship.split(" ");
			map.put(split[split.length - 1], split[0]);
		}
		return map.values().stream().toArray(String[]::new);
	}

	public static String[] findCaptain(String[] ships) {
		return Arrays.stream(ships)
				.map(s -> s.substring(0, s.indexOf("Captain")))
				.collect(Collectors.toList())
				.toArray(new String[0]);
	}
}
