package com.github.michaelruocco.codewars.solutions.kyu5;

import java.util.Arrays;

/**
 * <a href="https://www.codewars.com/kata/545a4c5a61aa4c6916000755">Find the middle element</a>
 * 
 * @author michaelruocco
 */
public class FindTheMiddleElement {
    public static int[] mid(int[] arr) {
        Arrays.sort(arr);
        int mid = arr.length / 2;
        if (arr.length % 2 == 0) {
            return new int[] { arr[mid], arr[mid - 1] };
        } else {
            return new int[] { arr[mid] };
        }
