package com.github.marekmy.codewars.katas.kyu8;

import java.util.ArrayList;
import java.util.List;

/**
 * <a href="https://www.codewars.com/kata/52597aa56021e91c93000cb0">Simple Encryption 1</a>
 * 
 * @author marekmy
 */
public class SimpleEncryption1 {
    /**
     * Encrypt the string.
     * 
     * @param text
     *            The text to encrypt.
     * @return The encrypted text.
     */
    public static String encrypt(String text) {
        // Check if the text is empty
        if (text.isEmpty()) {
            return text;
        }

        // Create the encrypted text
        StringBuilder encrypted = new StringBuilder();

        // Get the letters from the text
        List<Character> letters = new ArrayList<>();
        for (char c : text.toCharArray()) {
            if (Character.isLetter(c)) {
                letters.add(c);
            }
        }

        // Add the letters to the encrypted text
        for (int i = 0; i < letters.size(); i++) {
            Character letter = letters.get(i);

            // Add the letter to the encrypted text
            encrypted.append(letter);

            // Add the next letter
            if (i < letters.size() - 1) {
                encrypted.append(letters.get(i + 1));
            }
        }

        // Return the encrypted text
        return encrypted.toString();
    }
}
