            options.add("-encoding");
            options.add("UTF-8");
            options.add("-d");
            options.add("target/classes");
            options.add("-classpath");
            options.add("target/classes");
            options.add("-Xlint:all");
            options.add("-Xlint:-processing");
            options.add("-Xlint:-serial");
            options.add("-Xlint:-path");
            options.add("-Xlint:-try");

            List<JavaFileObject> files = new ArrayList<>();
            files.add(new JavaSourceFromString(source.getName(), IOUtils.toString(source, "UTF-8")));
            fileManager.getJavaFileObjectsFromFiles(files).stream().forEach(file -> {
                compiler.getTask(null, fileManager, diagnostics, options, null, fileManager.getJavaFileObjects(file)).call();
            });

            return diagnostics.getDiagnostics().stream().filter(diagnostic -> diagnostic.getKind().equals(Diagnostic.Kind.ERROR)).findFirst().map(diagnostic -> diagnostic.getMessage(null));
        }

