package com.github.codemonstur.codewars.katas.kyu6;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

/**
 * <a href="https://www.codewars.com/kata/disemvowel-trolls/train/java">Disemvowel Trolls</a>
 *
 * <p>Trolls are attacking your comment section!
 *
 * <p>A common way to deal with this situation is to remove all of the vowels from the trolls' comments, neutralizing the threat.
 *
 * <p>Your task is to write a function that takes a string and return a new string with all vowels removed.
 *
 * <p>For example, the string "This website is for losers LOL!" would become "Ths wbst s fr lsrs LL!".
 *
 * <p>Note: for this kata y isn't considered a vowel.
 *
 * @author codemonstur
 */
public class DisemvowelTrolls {
    @Test
    public void test() {
        Assertions.assertEquals("Ths wbst s fr lsrs LL!", disemvowel("This website is for losers LOL!"));
        Assertions.assertEquals("Hello World", disemvowel("Hello World"));
        Assertions.assertEquals("", disemvowel(""));
    }

    public static String disemvowel(String str) {
        List<String> vowels = Arrays.asList("a", "e", "i", "o", "u");
        return Arrays.stream(str.split(""))
               .filter(s ->!vowels.contains(s))
               .collect(Collectors.joining());
    }
}
