package com.codebattle.server.config.security.oauth2;

import com.codebattle.server.config.security.oauth2.model.OAuth2UserDetails;
import com.codebattle.server.service.auth.AuthService;
import lombok.RequiredArgsConstructor;
import org.springframework.security.core.Authentication;
import org.springframework.security.oauth2.provider.OAuth2Authentication;
import org.springframework.security.web.authentication.AuthenticationSuccessHandler;
import org.springframework.stereotype.Component;

import javax.servlet.ServletException;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

@Component
@RequiredArgsConstructor
public class OAuth2AuthenticationSuccessHandler implements AuthenticationSuccessHandler {

    private final AuthService authService;

    @Override
    public void onAuthenticationSuccess(HttpServletRequest request, HttpServletResponse response, Authentication authentication) throws IOException, ServletException {
        OAuth2Authentication auth = (OAuth2Authentication) authentication;
        OAuth2UserDetails userDetails = (OAuth2UserDetails) auth.getUserAuthentication().getPrincipal();
        authService.createOAuth2User(userDetails);
        response.sendRedirect("/");
    }
}
