package com.github.michalszyn.codewars.solutions.kyu8;

import java.util.stream.IntStream;

/**
 * https://www.codewars.com/kata/541c8630095125aba6000c00
 */
public class SumOfDigitsDigitalRoot {

    public static int digital_root(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum > 9? digital_root(sum) : sum;
    }

    public static int digital_root_recursive(int n) {
        if (n < 10) {
            return n;
        }
        return digital_root_recursive(IntStream.range(0, String.valueOf(n).length()).map(i -> n % 10).sum());
    }
}
