public class SimpleFun322 {

    public static int[] solution(int[] a) {
        int[] result = new int[a.length];
        for (int i = 0; i < a.length; i++) {
            result[i] = a[i] % 2 == 0? a[i] / 2 : a[i] / 2 + 1;
