using namespace std;

struct Node {
    int value;
    Node *left;
    Node *right;
};

struct Node *newNode(int value) {
    Node *node = new Node();
    node->value = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

int main() {
    int n;
    cin >> n;
    vector<int> values(n);
    for (int i = 0; i < n; i++) {
        cin >> values[i];
    }
    unordered_map<int, int> map;
    for (int i = 0; i < n; i++) {
        map[values[i]] = i;
    }
    vector<Node*> nodes(n, NULL);
    for (int i = 0; i < n; i++) {
        nodes[i] = newNode(values[i]);
    }
    for (int i = 0; i < n; i++) {
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        if (left < n) {
            nodes[i]->left = nodes[left];
        }
        if (right < n) {
            nodes[i]->right = nodes[right];
        }
    }
    int k;
