    vector<int> queries(k);
    for (int i = 0; i < k; i++) {
        cin >> queries[i];
    }
    for (int i = 0; i < k; i++) {
        int index = map[queries[i]];
        Node *node = nodes[index];
        while (node->left!= NULL) {
            node = node->left;
        }
        cout << node->value << endl;
    }
    return 0;
}
