package com.github.michaelruocco.codewars.kata.kyu6;

import java.util.Arrays;
import java.util.List;

/**
 * Build Tower
 *
 * Build Tower by the following given argument:
 * number of floors (integer and always greater than 0).
 *
 * Tower block is represented as *
 *
 * Python: return a list;
 * JavaScript: returns an Array;
 * C#: returns a string[];
 * PHP: returns an array;
 * C++: returns a vector<string>;
 * Ruby: returns an Array;
 * Rust: returns a Vec<String>;
 *
 * Have fun!
 *
 * For more information: https://www.codewars.com/kata/build-tower/train/java
 */
public class BuildTower {

    public static String[] towerBuilder(int nFloors) {
        List<String> result = Arrays.asList();
        for (int floor = 0; floor < nFloors; floor++) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < nFloors - floor - 1; i++) {
                sb.append(" ");
            }
            for (int i = 0; i < 2 * floor + 1; i++) {
                sb.append("*");
            }
            result.add(sb.toString());
        }
        return result.toArray(new String[result.size()]);
    }
}
