import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

@RestController
@RequestMapping("/api/v1/challenges")
public class ChallengeController {

    private final ChallengeService challengeService;

    @Autowired
    public ChallengeController(ChallengeService challengeService) {
        this.challengeService = challengeService;
    }

    @GetMapping("/{id}")
    public ResponseEntity<Challenge> findById(@PathVariable Long id) {
        return new ResponseEntity<>(challengeService.findById(id), HttpStatus.OK);
    }

    @GetMapping
    public ResponseEntity<List<Challenge>> findAll() {
        return new ResponseEntity<>(challengeService.findAll(), HttpStatus.OK);
    }

    @PostMapping
    public ResponseEntity<Challenge> create(@RequestBody Challenge challenge) {
        return new ResponseEntity<>(challengeService.create(challenge), HttpStatus.CREATED);
    }
}
