package com.websecurity.exercise.web.controller;

import com.websecurity.exercise.web.model.User;
import com.websecurity.exercise.web.service.UserService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.servlet.ModelAndView;

import java.util.Optional;

@Controller
@RequestMapping("/login")
public class LoginController {

    private final UserService userService;

    @Autowired
    public LoginController(UserService userService) {
        this.userService = userService;
    }

    @GetMapping
    public ModelAndView getLogin() {
        return new ModelAndView("login");
    }

    @PostMapping
    public ModelAndView postLogin(User user) {
        Optional<User> userOptional = userService.findUserByUsername(user.getUsername());
        if (userOptional.isPresent()) {
            User userFromDb = userOptional.get();
            if (userFromDb.getPassword().equals(user.getPassword())) {
                return new ModelAndView("redirect:/");
            }
        }
        return new ModelAndView("login");
    }
}
