    }

    public State(String name) {
        this();
        this.name = name;
    }

    public void addTransition(Transition t) {
        transitions.add(t);
    }

    public static class Transition {
        public String from;
        public String to;
        public String label;

        public Transition(String from, String to, String label) {
            this.from = from;
            this.to = to;
            this.label = label;
        }
    }
}
