package com.github.czyzby.kodilla.code.challenge.controller;

import com.github.czyzby.kodilla.code.challenge.service.CodeChallengeService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;

@Controller
public class CodeChallengeController {

    private final CodeChallengeService codeChallengeService;

    @Autowired
    public CodeChallengeController(CodeChallengeService codeChallengeService) {
        this.codeChallengeService = codeChallengeService;
    }

    @GetMapping("/{language}/{challenge}")
    public String getChallenge(@PathVariable String language, @PathVariable String challenge, Model model) {
        model.addAttribute("challenge", codeChallengeService.getChallenge(language, challenge));
        return "challenge";
    }
}
