 * 
 * @author 
 * @version 1.0
 * @since 2019-07-09
 */
public class Kata10 {

    public static void main(String[] args) {
        System.out.println(Arrays.toString(new Kata10().duplicateCount("aabBcde")));
        System.out.println(Arrays.toString(new Kata10().duplicateCount("Indivisibility")));
        System.out.println(Arrays.toString(new Kata10().duplicateCount("Indivisibilities")));
        System.out.println(Arrays.toString(new Kata10().duplicateCount("aA11")));
        System.out.println(Arrays.toString(new Kata10().duplicateCount("ABBA")));
    }

    public int duplicateCount(String text) {
        int[] count = new int[26];
        for (char c : text.toLowerCase().toCharArray()) {
            count[c - 'a']++;
        }
        int result = 0;
        for (int i : count) {
            result += i / 2;
        }
        return result;
    }
}
