import java.io.File;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.util.Scanner;

import com.github.gencayyildiz.kodlama.kodlama_v3.utils.exceptions.FileNotExistsException;
import com.github.gencayyildiz.kodlama.kodlama_v3.utils.exceptions.FileNotReadableException;

public class App {

	public static void main(String[] args) {
		File file = new File("src/main/java/com/github/gencayyildiz/kodlama/kodlama_v3/utils/test.txt");
		try {
			System.out.println(readFile(file));
		} catch (FileNotFoundException e) {
			e.printStackTrace();
		} catch (FileNotReadableException e) {
			e.printStackTrace();
		} catch (FileNotExistsException e) {
			e.printStackTrace();
		}
	}

	public static String readFile(File file) throws FileNotFoundException, FileNotReadableException, FileNotExistsException {
		if (!file.exists()) {
			throw new FileNotExistsException();
		}
		if (!file.canRead()) {
			throw new FileNotReadableException();
		}
		Scanner scanner = new Scanner(file);
		String result = "";
		while (scanner.hasNext()) {
			result += scanner.nextLine() + "\n";
		}
		scanner.close();
		return result;
	}

}
