import java.util.List;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import it.unical.mat.exams.model.Exam;
import it.unical.mat.exams.repository.ExamRepository;

@RestController
@RequestMapping("/exams")
public class ExamsController {
    @Autowired
    private ExamRepository examRepository;

    @GetMapping
    public ResponseEntity<List<Exam>> getExams() {
        return new ResponseEntity<>(examRepository.findAll(), HttpStatus.OK);
    }

    @GetMapping("/{id}")
    public ResponseEntity<Exam> getExam(@PathVariable("id") Long id) {
        return examRepository.findById(id).map(exam -> new ResponseEntity<>(exam, HttpStatus.OK))
               .orElseGet(() -> new ResponseEntity<>(HttpStatus.NOT_FOUND));
    }
}
