package com.github.septian_b.code_assistant;

import java.io.File;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Class untuk mengambil catatan dari basis data (disimulasikan).
 * 
 * Fungsi ini membersihkan input dengan memblokir kata kunci 'UNION'.
 * 
 * @author 
 */
public class CodeAssistant {
    /**
     * Mengambil catatan dari basis data (disimulasikan).
     * 
     * Fungsi ini membersihkan input dengan memblokir kata kunci 'UNION'.
     * 
     * @param input Input yang akan dibersihkan.
     * @return Output yang telah dibersihkan.
     */
    public static String clean(String input) {
        String[] keywords = {"UNION", "SELECT", "FROM", "JOIN"};
        List<String> keywordList = Arrays.asList(keywords);
        List<String> inputList = Arrays.asList(input.split("\\s+"));
        List<String> outputList = inputList.stream()
               .filter(x ->!keywordList.contains(x))
               .collect(Collectors.toList());
