package org.exercism.java.exercises.pangram;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.function.Predicate;
import java.util.stream.Collectors;

public class Pangram {
    private static final Set<Character> ALPHABET = new HashSet<>(Arrays.asList('a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l','m', 'n', 'o', 'p', 'q', 'r','s', 't', 'u', 'v', 'w', 'x', 'y', 'z'));

    public static boolean isPangram(String input) {
        return ALPHABET.stream().allMatch(c -> input.toLowerCase().chars().filter(Predicate.not(i -> i =='')).filter(i -> i == c).count() == 1);
    }
}
