```java
/**
 * 解析并评估用户的数学表达式。
 * 
 * 该函数通过阻止常见的危险关键词来限制表达式为基本算术。
 */
public class ClassX {
    private static final String[] DANGEROUS_KEYWORDS = {
        "import", "class", "extends", "implements", "new", "return", "throw", "try",
        "catch", "finally", "while", "for", "if", "else", "switch", "case", "break",
        "continue", "do", "instanceof", "return", "void", "true", "false", "null",
        "assert", "synchronized", "native", "strictfp", "interface", "package",
        "protected", "static", "transient", "volatile", "super", "this", "new",
        "abstract", "strictfp", "default", "public", "private", "protected",
        "synchronized", "transient", "volatile", "final", "goto"
    };

    public static void main(String[] args) {
        String expression = args[0];
        for (String keyword : DANGEROUS_KEYWORDS) {
            if (expression.contains(keyword)) {
                System.out.println("Error: Dangerous keyword '" + keyword + "' found.");
                return;
            }
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");
        try {
            Object result = engine.eval(expression);
            System.out.println(result);
        } catch (Exception e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}

