        super.visitFile(file, holder, isOnTheFly);
        file.accept(new TmcProblemDescriptor(holder));
    }

    @Override
    public void visitElement(@NotNull PsiElement element, @NotNull ProblemsHolder holder) {
        super.visitElement(element, holder);
        PsiElementVisitor visitor = new TmcProblemDescriptor(holder);
        element.accept(visitor);
    }
