	private String lexem;

	/**
	 * Type.
	 */
	private TokenType type;

	/**
	 * Constructeur par défaut.
	 * 
	 * @param lexem
	 *            Lexem correspondant au token.
	 * @param type
	 *            Type du token.
	 */
	public Token(String lexem, TokenType type) {
		this.lexem = lexem;
		this.type = type;
	}

	/**
	 * Récupère le lexem.
	 * 
	 * @return Lexem correspondant au token.
	 */
	public String getLexem() {
		return lexem;
	}

	/**
	 * Récupère le type.
	 * 
	 * @return Type du token.
	 */
	public TokenType getType() {
		return type;
	}

	/**
	 * Méthode toString.
	 * 
	 * @return String représentant le token.
	 */
	@Override
	public String toString() {
		return "Token [lexem=" + lexem + ", type=" + type + "]";
	}

}
