package org.elsys.jps.model;

import java.util.ArrayList;
import java.util.List;

public class JpsClass {
    private String name;
    private String superClassName;
    private List<JpsMethod> methods;

    public JpsClass(String name, String superClassName) {
        this.name = name;
        this.superClassName = superClassName;
        this.methods = new ArrayList<>();
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getSuperClassName() {
        return superClassName;
    }

    public void setSuperClassName(String superClassName) {
        this.superClassName = superClassName;
    }

    public List<JpsMethod> getMethods() {
        return methods;
    }

    public void setMethods(List<JpsMethod> methods) {
        this.methods = methods;
    }

    public void addMethod(JpsMethod method) {
        this.methods.add(method);
    }

    public JpsMethod getMethod(String name) {
        for (JpsMethod method : methods) {
            if (method.getName().equals(name)) {
                return method;
            }
        }
        return null;
    }

    public void removeMethod(JpsMethod method) {
        this.methods.remove(method);
