package de.tudarmstadt.ukp.clarin.webanno.api.dao;

import java.util.List;

import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import de.tudarmstadt.ukp.clarin.webanno.api.annotation.model.Project;
import de.tudarmstadt.ukp.clarin.webanno.api.annotation.model.User;
import de.tudarmstadt.ukp.clarin.webanno.security.model.Role;

public interface ProjectDao
    extends AnnotatedResourceDao<Project, Long>
{
    @Query("SELECT p FROM Project p JOIN p.roles r WHERE r.user = :user AND r.role = :role")
    List<Project> findProjectsForUserAndRole(@Param("user") User user, @Param("role") Role role);

    @Query("SELECT p FROM Project p JOIN p.roles r WHERE r.user = :user AND r.role = :role")
    Page<Project> findProjectsForUserAndRole(@Param("user") User user, @Param("role") Role role,
            Pageable aPageable);
}

