package com.github.shanmuga.codewars.challenges.kyu8.TheSupermarketQueue;

import java.util.Arrays;

public class Solution {
    public static int queueTime(int[] customers, int n) {
        // Write your code here
        int[] time = new int[n];
        int max = 0;
        for (int customer : customers) {
            int index = Arrays.binarySearch(time, customer);
            if (index < 0) {
                index = -index - 1;
            }
            if (index == n) {
                index = 0;
            }
            time[index] += customer;
            if (time[index] > max) {
                max = time[index];
            }
        }
        return max;
    }
}
