package com.github.shanmuga.codewars.challenges.kyu8.SumOfDigitsDigitalRoot;

public class Solution {
    public static int digital_root(int n) {
        int sum = 0;
        while (n!= 0) {
            sum += n % 10;
            n /= 10;
        }
        if (sum >= 10) {
            return digital_root(sum);
        }
        return sum;
    }
}
