package com.github.kodus.exercism.java.pangram;

import static java.util.stream.Collectors.joining;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.stream.Stream;

/**
 * Determine if a sentence is a pangram.
 * 
 * A pangram (Greek: παν γράμμα, pan gramma, "every letter") is a sentence using
 * every letter of the alphabet at least once. The best known English pangram is:
 * The quick brown fox jumps over the lazy dog.
 * 
 * The alphabet used consists of ASCII letters a to z, inclusive, and is case
 * insensitive. Input will not contain non-ASCII symbols.
 * 
 * @author <a href="mailto:"></a>
 */
public class Pangram {
    private static final Set<Character> ALPHABET = new HashSet<>(Arrays.asList('a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i',
            'j', 'k', 'l','m', 'n', 'o', 'p', 'q', 'r','s', 't', 'u', 'v', 'w', 'x', 'y', 'z'));

    public boolean isPangram(String input) {
        return Stream.of(input.toLowerCase().split(""))
               .map(String::valueOf)
               .map(Character::valueOf)
               .collect(joining())
               .chars()
               .mapToObj(c -> (char) c)
               .collect(joining())
               .chars()
               .mapToObj(c -> (char) c)
               .allMatch(ALPHABET::contains);
    }
}
