import java.util.Scanner;

public class p03_Vacation {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int groupSize = Integer.parseInt(scanner.nextLine());
        String destination = scanner.nextLine();
        String day = scanner.nextLine();

        double price = 0.0;

        switch (destination) {
            case "France":
                if (day.equals("Friday")) {
                    price = groupSize * 8.6;
                } else if (day.equals("Saturday")) {
                    price = groupSize * 10.2;
                } else if (day.equals("Sunday")) {
                    price = groupSize * 12.6;
                }
                break;
            case "Germany":
                if (day.equals("Friday")) {
                    price = groupSize * 11.2;
                } else if (day.equals("Saturday")) {
                    price = groupSize * 13.0;
                } else if (day.equals("Sunday")) {
                    price = groupSize * 14.4;
                }
                break;
        }

        if (groupSize >= 100) {
            price = price * 0.7;
        }

        if (groupSize >= 10 && groupSize <= 20) {
            price = price * 0.85;
        }

        System.out.printf("The price is %.2f", price);
    }
}
