package vn.edu.hust.cse.programming.exercise;

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

import vn.edu.hust.cse.programming.exercise.question.Question;

/**
 * Exercise class
 * 
 * @author 
 * @version 1.0
 */
public class Exercise {
    private String name;
    private String description;
    private List<Question> questions;

    /**
     * Constructor
     * 
     * @param name
     *            name of exercise
     * @param description
     *            description of exercise
     * @param questions
     *            list of questions
     */
    public Exercise(String name, String description, List<Question> questions) {
        this.name = name;
        this.description = description;
        this.questions = questions;
    }

    /**
     * Constructor
     * 
     * @param name
     *            name of exercise
     * @param description
     *            description of exercise
     */
    public Exercise(String name, String description) {
        this(name, description, new ArrayList<Question>());
    }

    /**
     * Constructor
     * 
     * @param name
     *            name of exercise
     */
    public Exercise(String name) {
        this(name, "");
    }

    /**
     * Get name of exercise
     * 
     * @return name of exercise
     */
    public String getName() {
        return name;
    }

    /**
     * Get description of exercise
     * 
     * @return description of exercise
     */
    public String getDescription() {
        return description;
    }

    /**
     * Get list of questions
     * 
     * @return list of questions
     */
    public List<Question> getQuestions() {
        return questions;
    }

    /**
     * Add question to exercise
     * 
     * @param question
     *            question to be added
     */
    public void addQuestion(Question question) {
        this.questions.add(question);
    }

    /**
     * Remove question from exercise
     * 
     * @param question
     *            question to be removed
