package com.github.victorskl.codewars.codewars.kyu6;

import java.util.Arrays;
import java.util.List;
import java.util.stream.IntStream;

/**
 * The Supermarket Queue
 * https://www.codewars.com/kata/the-supermarket-queue/train/java
 */
public class TheSupermarketQueue {
    public static int queueTime(int[] customers, int n) {
        if (customers.length == 0) {
            return 0;
        }
        int[] tills = new int[n];
        Arrays.fill(tills, 0);
        int time = 0;
        while (IntStream.of(customers).max().orElse(0) > 0) {
            for (int i = 0; i < tills.length; i++) {
                if (customers.length == 0) {
                    break;
                }
                if (tills[i] == 0) {
                    tills[i] = customers[0];
                    customers = Arrays.copyOfRange(customers, 1, customers.length);
                } else {
                    tills[i]--;
                }
            }
            time++;
        }
        return time;
    }
}
