package com.github.sahib.code.generator.template;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import com.github.sahib.code.generator.Config;
import com.github.sahib.code.generator.Generator;
import com.github.sahib.code.generator.util.FileUtils;
import com.github.sahib.code.generator.util.TemplateUtils;

public class CodeGenerator implements Generator {
    private final String template;
    private final Map<String, Object> data;

    public CodeGenerator(String template, Map<String, Object> data) {
        this.template = template;
        this.data = data;
    }

    public CodeGenerator(String template) {
        this(template, new HashMap<>());
    }

    @Override
    public void generate(Config config) throws IOException {
        String code = TemplateUtils.render(template, data);
        FileUtils.write(new File(config.getOutDir(), config.getOutName()), code);
    }

    @Override
    public List<String> getDependencies() {
        return new ArrayList<>();
    }
}
