package com.github.sahib.code.generator.util;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.util.Map;

import com.github.sahib.code.generator.template.Template;
import com.github.sahib.code.generator.template.TemplateEngine;

public class TemplateUtils {
    public static String render(String template, Map<String, Object> data) throws IOException {
        Writer writer = new StringWriter();
        TemplateEngine engine = new TemplateEngine();
        Template templateObj = engine.getTemplate(template);
        templateObj.process(data, writer);
        return writer.toString();
    }
}
