```cpp
#include <bits/stdc++.h>
using namespace std;

#define fi first
#define se second
#define pb push_back
#define mp make_pair
#define MOD 1000000007
#define pii pair<int,int>
#define pli pair<long long,int>
#define pil pair<int,long long>
#define ll long long
#define el '\n'

const int N = 2e5 + 5;

int n, a[N], b[N], x, y;

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);

    cin >> n;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
    }
    for (int i = 1; i <= n; i++) {
        cin >> b[i];
    }

    for (int i = 1; i <= n; i++) {
        if (a[i] == 0) {
            x = i;
        }
        if (b[i] == 0) {
            y = i;
        }
    }

    if (x > y) {
        swap(x, y);
    }

    if (x == y) {
        cout << x << el;
    } else {
        cout << 0 << el;
    }

    return 0;
}
