package fr.umlv.trace.assistant;

import java.io.IOException;
import java.io.PrintWriter;
import java.io.StringWriter;
import java.util.ArrayList;
import java.util.List;

import fr.umlv.trace.Trace;
import fr.umlv.trace.Trace.Level;

public class Assistant {
    private final List<AssistantListener> listeners = new ArrayList<>();

    public void addListener(AssistantListener listener) {
        this.listeners.add(listener);
    }

    public void removeListener(AssistantListener listener) {
        this.listeners.remove(listener);
    }

    public void execute(Trace trace, String code, String userCode) {
        try {
            StringWriter stringWriter = new StringWriter();
            PrintWriter printWriter = new PrintWriter(stringWriter);
            printWriter.println(code);
            printWriter.close();
            String codeWithoutAssistant = stringWriter.toString();
            StringWriter stringWriterWithoutAssistant = new StringWriter();
            PrintWriter printWriterWithoutAssistant = new PrintWriter(stringWriterWithoutAssistant);
            printWriterWithoutAssistant.println(userCode);
            printWriterWithoutAssistant.close();
            String userCodeWithoutAssistant = stringWriterWithoutAssistant.toString();
            for (AssistantListener listener : this.listeners) {
                listener.onExecute(trace, codeWithoutAssistant, userCodeWithoutAssistant);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void onLevelChange(Trace trace) {
        for (AssistantListener listener : this.listeners) {
            listener.onLevelChange(trace);
        }
    }

    public void onLevelChange(Trace trace, Level level) {
        for (AssistantListener listener : this.listeners) {
            listener.onLevelChange(trace, level);
        }
    }
}
