import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

import edu.cmu.cs.stage3.alice.core.property.PropertyTable.PropertyTableIterator;
import edu.cmu.cs.stage3.alice.core.property.PropertyTable.PropertyTableIterator.PropertyTableIteratorDirection;

public class PropertyTable {
	private List<PropertyTableRow> _rows = new ArrayList<PropertyTableRow>();
	private Map<String, PropertyTableRow> _rowMap = new HashMap<String, PropertyTableRow>();

	public PropertyTable() {
	}

	public void addRow(PropertyTableRow row) {
		_rows.add(row);
		_rowMap.put(row.getKey(), row);
	}

	public void removeRow(PropertyTableRow row) {
		_rows.remove(row);
		_rowMap.remove(row.getKey());
	}

	public PropertyTableRow getRow(String key) {
		return _rowMap.get(key);
	}

	public PropertyTableRowIterator getRows() {
		return new PropertyTableIterator(_rows, PropertyTableIteratorDirection.FORWARD);
	}

	public PropertyTableRowIterator getRows(PropertyTableIteratorDirection direction) {
		return new PropertyTableIterator(_rows, direction);
	}

	public static class PropertyTableRowIterator implements Iterator<PropertyTableRow> {
		private List<PropertyTableRow> _rows;
		private PropertyTableIteratorDirection _direction;
		private int _index;

		public PropertyTableRowIterator(List<PropertyTableRow> rows, PropertyTableIteratorDirection direction) {
			_rows = rows;
			_direction = direction;
			if (_direction == PropertyTableIteratorDirection.FORWARD) {
				_index = 0;
			} else {
				_index = _rows.size() - 1;
			}
		}

		public boolean hasNext() {
			return _index >= 0 && _index < _rows.size();
		}

