package com.github.javaparser.ast.body;

import com.github.javaparser.ast.Node;
import com.github.javaparser.ast.NodeList;
import com.github.javaparser.ast.expr.Expression;
import com.github.javaparser.ast.type.ClassOrInterfaceType;
import com.github.javaparser.ast.type.Type;

public class MethodDeclaration extends Node {

    private final Type type;
    private final String name;
    private final NodeList<Expression> parameters;
    private final NodeList<VariableDeclarator> thrownExceptions;
    private final NodeList<ClassOrInterfaceType> typeParameters;
    private final NodeList<Statement> body;

    public MethodDeclaration(Type type, String name, NodeList<Expression> parameters,
        NodeList<VariableDeclarator> thrownExceptions, NodeList<ClassOrInterfaceType> typeParameters,
        NodeList<Statement> body) {
        this.type = type;
        this.name = name;
        this.parameters = parameters;
        this.thrownExceptions = thrownExceptions;
        this.typeParameters = typeParameters;
        this.body = body;
    }

    public Type getType() {
        return type;
    }

    public String getName() {
        return name;
    }

    public NodeList<Expression> getParameters() {
        return parameters;
    }

    public NodeList<VariableDeclarator> getThrownExceptions() {
        return thrownExceptions;
    }

    public NodeList<ClassOrInterfaceType> getTypeParameters() {
        return typeParameters;
    }

    public NodeList<Statement> getBody() {
        return body;
    }

    @Override
    public String toString() {
        return "MethodDeclaration [type=" + type + ", name=" + name + ", parameters=" + parameters
            + ", thrownExceptions=" + thrownExceptions + ", typeParameters=" + typeParameters + ", body=" + body + "]";
    }

}
