import nl.han.ica.icss.ast.node.expression.Identifier;
import nl.han.ica.icss.ast.node.expression.Variable;
import nl.han.ica.icss.ast.node.expression.Variable.VariableType;
import nl.han.ica.icss.ast.node.statement.ClassBody;

public class ClassDeclaration extends Declaration {

	private String className;
	private ClassBody classBody;

	public ClassDeclaration(String className, ClassBody classBody) {
		this.className = className;
		this.classBody = classBody;
	}

	public String getClassName() {
		return className;
	}

	public void setClassName(String className) {
		this.className = className;
	}

	public ClassBody getClassBody() {
		return classBody;
	}

	public void setClassBody(ClassBody classBody) {
		this.classBody = classBody;
	}

	@Override
	public String toString() {
		return "ClassDeclaration [className=" + className + ", classBody=" + classBody + "]";
	}

	@Override
	public Node accept(NodeVisitor visitor) {
		return visitor.visit(this);
	}

	public Variable getVariable() {
		return new Variable(className, VariableType.CLASS);
	}

	public Identifier getIdentifier() {
		return new Identifier(className);
	}
}
