package com.github.saphyra.apphub.service.impl.util;

import com.github.saphyra.apphub.service.impl.util.exception.ClassNotFoundException;
import lombok.experimental.UtilityClass;

import java.io.IOException;
import java.io.InputStream;
import java.net.URL;
import java.net.URLClassLoader;
import java.util.Enumeration;
import java.util.jar.JarEntry;
import java.util.jar.JarFile;

@UtilityClass
public class ClassUtil {
    public Class<?> loadClass(String className, ClassLoader classLoader) {
        try {
            return Class.forName(className, false, classLoader);
        } catch (ClassNotFoundException e) {
            throw new ClassNotFoundException("Class not found: " + className, e);
        }
    }

    public Class<?> loadClass(String className) {
        return loadClass(className, Thread.currentThread().getContextClassLoader());
    }

    public Class<?> loadClass(String className, URL url) {
        return loadClass(className, url.openStream());
    }

    public Class<?> loadClass(String className, InputStream inputStream) {
        try {
            return loadClass(className, new URLClassLoader(new URL[] {urlFromInputStream(inputStream)}, Thread.currentThread().getContextClassLoader()));
        } catch (IOException e) {
            throw new ClassNotFoundException("Class not found: " + className, e);
        }
    }

    public Class<?> loadClass(String className, JarFile jarFile) {
        try {
            return loadClass(className, new URLClassLoader(new URL[] {jarFile.toURI().toURL()}, Thread.currentThread().getContextClassLoader()));
        } catch (IOException e) {
            throw new ClassNotFoundException("Class not found: " + className, e);
        }
    }

    public Class<?> loadClass(String className, Enumeration<JarEntry> jarEntries) {
        try {
            return loadClass(className, new URLClassLoader(new URL[] {jarEntriesToURL(jarEntries)}, Thread.currentThread().getContextClassLoader()));
        } catch (IOException e) {
            throw new ClassNotFoundException("Class not found: " + className, e);
        }
    }

