    }

    public static int[] solution(int[] arr, int k) {
        int[] result = new int[arr.length];
        int[] temp = new int[arr.length];
        int count = 0;
        int index = 0;

        for (int i = 0; i < arr.length; i++) {
            if (arr[i]!= k) {
                temp[index] = arr[i];
                index++;
            } else {
                count++;
            }
        }

        index = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == k) {
                result[i] = temp[index];
                index++;
            } else {
                result[i] = arr[i];
            }
        }

        return result;
    }

}
