import React, { Component } from'react';
import { connect } from'react-redux';
import { Link } from'react-router-dom';
import { getSolutions } from '../actions';

class SolutionList extends Component {
  componentDidMount() {
    this.props.getSolutions();
  }

  render() {
    const { solutions } = this.props;
    return (
      <div>
        <h1>Solutions</h1>
        <ul>
          {solutions &&
            solutions.map(solution => (
              <li key={solution.id}>
                <Link to={`/solutions/${solution.id}`}>{solution.title}</Link>
              </li>
            ))}
        </ul>
      </div>
    );
  }
}

const mapStateToProps = ({ solutions }) => ({
  solutions: solutions.all
});

export default connect(
  mapStateToProps,
  { getSolutions }
)(SolutionList);
