        this.sourcePath = sourcePath;
        this.className = className;
        this.mainClass = mainClass;
        this.mainClassName = mainClassName;
        this.imports = imports;
    }

    @Override
    public void generate(File directory) throws IOException {
        File file = new File(directory, sourcePath + ".java");
        file.createNewFile();
        file.deleteOnExit();

        JavaFileWriter fileWriter = new JavaFileWriter(file);

        fileWriter.writePackage(packagePath);
        fileWriter.writeImports(imports);
        fileWriter.writeClass(className, mainClass);
        fileWriter.writeMain(mainClassName);
    }

