     */
    public static boolean verifyToken(String token, String key, Map<String, String> supportedAlgorithms) {
        // Get header
        String header = token.split("\\.")[0];
        // Get payload
        String payload = token.split("\\.")[1];
        // Get signature
        String signature = token.split("\\.")[2];
        // Get all header information
        Map<String, String> headerMap = new HashMap<>();
        for (String s : header.split("\\,")) {
            String[] keyAndValue = s.split("\\=");
            if (keyAndValue.length == 2) {
                headerMap.put(keyAndValue[0].trim(), keyAndValue[1].trim());
            }
        }
        // Get algorithm
        String algorithm = headerMap.get("alg");
        // Check signature
        if (algorithm.equals("none")) {
            return true;
        } else if (supportedAlgorithms.containsKey(algorithm)) {
            String[] secretAndHash = supportedAlgorithms.get(algorithm).split("\\:");
            String secret = secretAndHash[0];
            String hash = secretAndHash[1];
            String calculatedHash = Base64.getEncoder().encodeToString(Base64.getDecoder().decode(hash));
            String calculatedSignature = Base64.getEncoder().encodeToString(Base64.getDecoder().decode(signature));
            return calculatedHash.equals(calculatedSignature);
        } else {
            return false;
        }
    }
