    String[] headerParts = headerPart.split("\\.");
    String[] payloadParts = payloadPart.split("\\.");
    for (String part : headerParts) {
        String[] keyValue = part.split("=");
        header.put(keyValue[0], keyValue[1]);
    }
    for (String part : payloadParts) {
        String[] keyValue = part.split("=");
        payload.put(keyValue[0], keyValue[1]);
    }
    String algorithm = header.get("alg");
    if (algorithm == null) {
        return false;
    }
    if ("none".equals(algorithm)) {
        return true;
    }
    if ("HS256".equals(algorithm)) {
        String secret = payload.get("secret");
        if (secret == null) {
            return false;
