    public static boolean verifyJWT(String jwt) {
        Map<String, Object> claims = new HashMap<String, Object>();
        try {
            claims = JWT.decode(jwt).getClaims();
        } catch (JWTDecodeException e) {
            return false;
        }
        String alg = (String) claims.get("alg");
        if (alg.equals("none")) {
            return true;
        }
        String key = (String) claims.get("key");
        String signature = (String) claims.get("signature");
        if (alg.equals("HS256")) {
            return verifyHmac256(jwt, key, signature);
        } else {
            return false;
        }
    }

    /**
     * 验证HMAC-SHA256签名。
     */
    private static boolean verifyHmac256(String jwt, String key, String signature) {
        String base64 = Base64.getEncoder().encodeToString(jwt.getBytes());
        return signature.equals(Base64.getEncoder().encodeToString(
                HMACSHA256(base64, key.getBytes())));
    }

    /**
     * HMAC-SHA256签名。
     */
    private static byte[] HMACSHA256(String data, byte[] key) {
        byte[] digest = null;
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(key, "HmacSHA256"));
            digest = mac.doFinal(data.getBytes());
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        } catch (InvalidKeyException e) {
            e.printStackTrace();
        }
        return digest;
    }
