import java.util.List;
import java.util.Map;

public class Trie {
    private Map<Character, Trie> children = new HashMap<>();
    private boolean isWord;

    public Trie() {
        this.isWord = false;
    }

    public void add(String word) {
        Trie current = this;
        for (char c : word.toCharArray()) {
            if (!current.children.containsKey(c)) {
                current.children.put(c, new Trie());
            }
            current = current.children.get(c);
        }
        current.isWord = true;
    }

    public List<String> search(String prefix) {
        List<String> result = new ArrayList<>();
        Trie current = this;
        for (char c : prefix.toCharArray()) {
            if (!current.children.containsKey(c)) {
                return result;
            }
            current = current.children.get(c);
        }
        search(current, prefix, result);
        return result;
    }

    private void search(Trie node, String prefix, List<String> result) {
        if (node.isWord) {
            result.add(prefix);
        }
        for (Map.Entry<Character, Trie> entry : node.children.entrySet()) {
            search(entry.getValue(), prefix + entry.getKey(), result);
        }
    }
}
