package ru.spbau.mit.java.task1.task2;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

import ru.spbau.mit.java.task1.task1.Task1;

/**
 * Задача 2. Реализовать метод, который выводит все файлы и подкаталоги заданного каталога,
 * оканчивающиеся на заданное расширение.
 */
public class Task2 {

    /**
     * Выводит все файлы и подкаталоги заданного каталога, оканчивающиеся на заданное расширение.
     *
     * @param path путь к каталогу
     * @param extension расширение
     * @throws IOException
     */
    public static void printFiles(String path, String extension) throws IOException {
        File dir = new File(path);
        if (!dir.isDirectory()) {
            throw new IOException("Path is not a directory");
        }

        List<File> files = new ArrayList<>();
        files.addAll(Collections.list(dir.listFiles()));

        Collections.sort(files, new Comparator<File>() {
            @Override
            public int compare(File o1, File o2) {
                return o1.getName().compareTo(o2.getName());
            }
        });

        for (File file : files) {
            if (file.isFile()) {
                if (file.getName().endsWith(extension)) {
                    System.out.println(file.getName());
                }
            } else if (file.isDirectory()) {
                System.out.println(file.getName());
            }
        }
    }

    public static void main(String[] args) throws IOException {
        String path = Task1.getPath();
        String extension = Task1.getExtension();
        printFiles(path, extension);
    }
}
