import java.util.ArrayList;
import java.util.List;

import com.github.albertcht.java.exercises.exercise.Exercise.ExerciseType;

public class Exercise {
    private String title;
    private String description;
    private ExerciseType type;
    private List<String> code;

    public Exercise(String title, String description, ExerciseType type) {
        this.title = title;
        this.description = description;
        this.type = type;
        this.code = new ArrayList<>();
    }

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public ExerciseType getType() {
        return type;
    }

    public void setType(ExerciseType type) {
        this.type = type;
    }

    public List<String> getCode() {
        return code;
    }

    public void setCode(List<String> code) {
        this.code = code;
    }

    public void addCode(String code) {
        this.code.add(code);
    }

    public void clearCode() {
        this.code.clear();
    }

    @Override
    public String toString() {
        return "Exercise [title=" + title + ", description=" + description + ", type=" + type + ", code=" + code + "]";
    }

    public enum ExerciseType {
        JAVA,
        PYTHON,
        SQL
    }
}
