		vrList.remove(0);
		vr.setParams(params);
		return vr;
	}

	public void addVR(VR vr) {
		vrList.add(vr);
	}

	public void addVR(List<VR> vrList) {
		this.vrList.addAll(vrList);
	}

	public void setParams(Map<String, String> params) {
