package nl.tudelft.model;

import java.util.ArrayList;
import java.util.List;

/**
 * A Code is a piece of code that can be executed.
 */
public class Code {

    private String code;
    private List<String> imports;
    private List<String> importsFrom;

    /**
     * Constructs a new Code object.
     *
     * @param code the code to be executed
     */
    public Code(String code) {
        this.code = code;
        this.imports = new ArrayList<>();
        this.importsFrom = new ArrayList<>();
    }

    /**
     * Adds an import to the code.
     *
     * @param importClass the class to import
     */
    public void addImport(String importClass) {
        this.imports.add(importClass);
    }

    /**
     * Adds an import from to the code.
     *
     * @param importClass the class to import from
     */
    public void addImportFrom(String importClass) {
        this.importsFrom.add(importClass);
    }

    /**
     * Gets the code.
     *
     * @return the code
     */
    public String getCode() {
        return code;
    }

    /**
     * Gets the imports.
     *
     * @return the imports
     */
    public List<String> getImports() {
        return imports;
    }

    /**
     * Gets the imports from.
     *
     * @return the imports from
     */
    public List<String> getImportsFrom() {
        return importsFrom;
    }
}
