public class Haxxor implements Serializable {
    private static final long serialVersionUID = 1L;

    private String code;
    private String output;

    public Haxxor(String code, String output) {
        this.code = code;
        this.output = output;
    }

    public String getCode() {
        return code;
    }

    public String getOutput() {
        return output;
    }

    public String getCodeAndOutput() {
        return code + output;
    }

    public String getBase64CodeAndOutput() {
        return Base64.getEncoder().encodeToString(serialize(this));
    }

    public static Haxxor deserialize(String base64) {
        try {
            return (Haxxor) deserialize(Base64.getDecoder().decode(base64));
        } catch (IOException | ClassNotFoundException e) {
            return null;
        }
    }

    private static Object deserialize(byte[] bytes) throws IOException, ClassNotFoundException {
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
                ObjectOutputStream oos = new ObjectOutputStream(baos)) {
            oos.writeObject(bytes);
            oos.close();
            return Utils.deserialize(baos.toByteArray());
        }
    }

    private static byte[] serialize(Object obj) throws IOException {
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
                ObjectOutputStream oos = new ObjectOutputStream(baos)) {
            oos.writeObject(obj);
            oos.close();
            return baos.toByteArray();
        }
    }
}
