package com.github.jankroken.fry.model;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.github.jankroken.fry.model.user.User;

import java.util.ArrayList;
import java.util.List;

public class Challenge {
    private final String id;
    private final String name;
    private final String description;
    private final String category;
    private final String difficulty;
    private final String language;
    private final String solution;
    private final List<String> hints = new ArrayList<>();
    private final User author;

    @JsonCreator
    public Challenge(@JsonProperty("id") String id,
                     @JsonProperty("name") String name,
                     @JsonProperty("description") String description,
                     @JsonProperty("category") String category,
                     @JsonProperty("difficulty") String difficulty,
                     @JsonProperty("language") String language,
                     @JsonProperty("solution") String solution,
                     @JsonProperty("hints") List<String> hints,
                     @JsonProperty("author") User author) {
        this.id = id;
        this.name = name;
        this.description = description;
        this.category = category;
        this.difficulty = difficulty;
        this.language = language;
        this.solution = solution;
        this.hints = hints;
        this.author = author;
    }

    public String getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getDescription() {
        return description;
    }

    public String getCategory() {
        return category;
    }

    public String getDifficulty() {
        return difficulty;
    }

    public String getLanguage() {
        return language;
    }

    public String getSolution() {
        return solution;
    }

    public List<String> getHints() {
        return hints;
    }

    public User getAuthor() {
        return author;
    }
}
