package hu.elte.prg2.prog2.utils;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.util.Base64;

public class CodeUtils {
    /**
     * Serializálja a bemeneti objektumot a {@link Base64} alapú kódolással.
     * 
     * @param obj a bemeneti objektum
     * @return a serializált objektum
     * @throws IOException
     */
    public static String serialize(Serializable obj) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(baos);
        oos.writeObject(obj);
        oos.close();
        return Base64.getEncoder().encodeToString(baos.toByteArray());
    }

    /**
     * Deserializálja a bemeneti {@link String} objektumot a {@link Base64} alapú kódolással.
     * 
     * @param str a bemeneti {@link String} objektum
     * @return a deserializált objektum
     * @throws IOException
     * @throws ClassNotFoundException
     */
    public static Serializable deserialize(String str) throws IOException, ClassNotFoundException {
        byte[] bytes = Base64.getDecoder().decode(str);
        ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
        ObjectInputStream ois = new ObjectInputStream(bais);
        return (Serializable) ois.readObject();
    }
}
