package org.elsys.javacup.cup.ast.nodes;

import java.util.ArrayList;
import java.util.List;

import org.elsys.javacup.cup.ast.ASTNode;
import org.elsys.javacup.cup.ast.ASTNodeType;

public class ClassNode extends ASTNode {
    private String name;
    private List<FieldNode> fields = new ArrayList<>();
    private List<MethodNode> methods = new ArrayList<>();

    public ClassNode(String name) {
        super(ASTNodeType.CLASS, null);
        this.name = name;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public List<FieldNode> getFields() {
        return fields;
    }

    public void setFields(List<FieldNode> fields) {
        this.fields = fields;
    }

    public List<MethodNode> getMethods() {
        return methods;
    }

    public void setMethods(List<MethodNode> methods) {
        this.methods = methods;
    }

    public void addMethod(MethodNode method) {
        methods.add(method);
    }

    public void addField(FieldNode field) {
        fields.add(field);
    }
}
