package nl.tudelft.ti2206.assignment3.util;

import java.io.File;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Util class.
 */
public class Util {
    /**
     * Find all occurrences of a regex pattern in a string.
     *
     * @param text the text
     * @param regex the regex
     * @return the list
     */
    public static List<String> findAll(String text, String regex) {
        Pattern p = Pattern.compile(regex);
        Matcher m = p.matcher(text);
        java.util.List<String> matches = java.util.Collections.list(m.results());
        return matches;
    }

    /**
     * Find all occurrences of a regex pattern in a file.
     *
     * @param file the file
     * @param regex the regex
     * @return the list
     */
    public static List<String> findAll(File file, String regex) {
        return findAll(FileIO.readFile(file), regex);
    }
}

