package com.github.kokorin.jcourse.model;

import java.util.List;

import com.github.kokorin.jcourse.model.answer.Answer;
import com.github.kokorin.jcourse.model.answer.AnswerType;
import com.github.kokorin.jcourse.model.answer.CodeAnswer;
import com.github.kokorin.jcourse.model.answer.InputOutputAnswer;
import com.github.kokorin.jcourse.model.answer.TextAnswer;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class Question {
    private String title;
    private String body;
    private String code;
    private String hint;
    private List<Answer> answers;

    public AnswerType getAnswerType() {
        if (answers == null || answers.isEmpty()) {
            return null;
        }
        AnswerType answerType = answers.get(0).getAnswerType();
        for (Answer answer : answers) {
            if (answer.getAnswerType()!= answerType) {
                return null;
            }
        }
        return answerType;
    }

    public boolean isCorrect(Answer answer) {
        if (getAnswerType() == null) {
            return false;
        }
        switch (getAnswerType()) {
        case TEXT:
            return ((TextAnswer) answer).getText().equals(((TextAnswer) answers.get(0)).getText());
        case CODE:
            return ((CodeAnswer) answer).getCode().equals(((CodeAnswer) answers.get(0)).getCode());
        case INPUT_OUTPUT:
            return ((InputOutputAnswer) answer).getInput().equals(((InputOutputAnswer) answers.get(0)).getInput())
                    && ((InputOutputAnswer) answer).getOutput().equals(
                            ((InputOutputAnswer) answers.get(0)).getOutput());
        default:
            return false;
        }
    }
}
