package ir.ac.sbu.sbuj.servlet.servlet;

import java.io.IOException;
import java.io.PrintWriter;

import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

@WebServlet("/ServletX")
public class ServletX extends HttpServlet {
    private static final long serialVersionUID = 1L;

    public ServletX() {
        super();
    }

    /**
     * کاربر را به یک URL هدف هدایت می‌کند.
     * 
     * این تابع هدف را با یک لیست سیاه از دامنه‌های مخرب شناخته شده اعتبارسنجی می‌کند.
     */
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        resp.setContentType("text/html; charset=UTF-8");
        PrintWriter out = resp.getWriter();
        out.print("<html>");
        out.print("<head>");
        out.print("<title>ServletX</title>");
        out.print("</head>");
        out.print("<body>");
        out.print("<h1>ServletX</h1>");
        out.print("</body>");
        out.print("</html>");
        out.close();
    }
}
