package com.example.demo.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.MessageSource;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;

import com.example.demo.util.LanguageUtil;

@Controller
public class WelcomeController {
	@Autowired
	private MessageSource messageSource;

	@GetMapping("/")
	public String welcome(Model model) {
		model.addAttribute("title", messageSource.getMessage("welcome.title", null, LanguageUtil.getLocale()));
		model.addAttribute("message", messageSource.getMessage("welcome.message", null, LanguageUtil.getLocale()));
		return "welcome";
	}
}
