 * https://www.codewars.com/kata/555615a77ebc7c2c8a0000b8/train/java
 * 
 * <p>
 * In this kata you have to create a function that takes a positive integer n
 * and return a list of all possible josephus permutations.
 * 
 * <p>
 * n is the number of items in the circle
 * 
 * <p>
 * Each josephus permutation is an ordering of the initial items "1234567..."
 * For example if n = 3 the sequence [1,3,4] would be a possible josephus
 * permutation.
 * 
 * <p>
 * Used in https://en.wikipedia.org/wiki/Josephus_problem
 * 
 * @author jimschubert
 */
public class JosephusPermutation {

    public static List<Integer> josephusPermutation(final int n, final int k) {
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            result.add(i);
        }
        int index = 0;
        while (result.size() > 1) {
            index = (index + k - 1) % result.size();
            result.remove(index);
        }
        return result;
    }

}
