package com.github.taycal.taycal.model;

import java.util.ArrayList;
import java.util.List;

import org.apache.commons.lang3.StringUtils;

import com.github.taycal.taycal.Taycal;
import com.github.taycal.taycal.TaycalConfig;
import com.github.taycal.taycal.TaycalException;
import com.github.taycal.taycal.TaycalUtils;
import com.github.taycal.taycal.model.TaycalModel.Type;

public class TaycalModel {
    public enum Type {
        ASSISTANT,
        USER,
        SYSTEM
    }

    private String message;
    private Type type;
    private List<String> code = new ArrayList<String>();

    public TaycalModel(String message, Type type) {
        this.message = message;
        this.type = type;
    }

    public String getMessage() {
        return message;
    }

    public Type getType() {
        return type;
    }

    public List<String> getCode() {
        return code;
    }

    public void addCode(String code) {
        this.code.add(code);
    }

    public void addCode(List<String> code) {
        this.code.addAll(code);
    }

    public void addCode(TaycalModel model) {
        this.code.addAll(model.getCode());
    }

    public String getCodeAsString() {
        StringBuilder builder = new StringBuilder();
        for (String line : code) {
            builder.append(line).append(System.lineSeparator());
        }
        return builder.toString();
    }

    public String getCodeAsBase64() {
        return TaycalUtils.encodeBase64(getCodeAsString());
    }

    public String getCodeAsBase64(boolean isSystem) {
        String code = getCodeAsBase64();
        if (isSystem) {
            code = StringUtils.replace(code, "import java.util.Base64;", "import java.util.Base64;");
        }
        return code;
    }

