package com.github.murilopereirawd.jokemaker.service;

import com.github.murilopereirawd.jokemaker.model.Joker;
import com.github.murilopereirawd.jokemaker.model.JokerType;
import com.github.murilopereirawd.jokemaker.repository.JokerRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.List;

@Service
public class JokerService {

    @Autowired
    private JokerRepository jokerRepository;

    public Joker createJoker(Joker joker) {
        return jokerRepository.save(joker);
    }

    public List<Joker> getAllJokers() {
        return jokerRepository.findAll();
    }

    public Joker getJokerById(Long id) {
        return jokerRepository.findById(id).orElseThrow();
    }

    public List<Joker> getAllJokersByType(JokerType jokerType) {
        return jokerRepository.findAllByType(jokerType);
    }

    public Joker updateJoker(Joker joker) {
        return jokerRepository.save(joker);
    }

    public void deleteJoker(Long id) {
        jokerRepository.deleteById(id);
    }
}
