package com.github.mdelapenya.codewars.kyu8;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

/**
 * <https://www.codewars.com/kata/the-deaf-rats-of-hamelin>
 */
public class TheDeafRatsOfHamelin {

    public static String deafRats(String rats) {
        List<String> ratsList = Arrays.stream(rats.split("\\s+")).collect(Collectors.toList());
        return ratsList.stream()
               .map(String::toLowerCase)
               .map((s) -> s.substring(0, 1).toUpperCase() + s.substring(1))
               .collect(Collectors.joining(" "));
    }
}
