package fr.kaliop.kaliop_java_server.question.response;

import java.util.ArrayList;
import java.util.List;

import fr.kaliop.kaliop_java_server.question.response.exception.ResponseException;

public class Response {
	private List<String> responses;

	public Response() {
		this.responses = new ArrayList<String>();
	}

	public void addResponse(String response) throws ResponseException {
		if (response == null || response.isEmpty()) {
			throw new ResponseException("La réponse ne peut être vide.");
		}
		if (responses.contains(response)) {
			throw new ResponseException("La réponse existe déjà.");
		}
		responses.add(response);
	}

	public List<String> getResponses() {
		return responses;
	}
}
