package com.github.misterchang.codewars.kyu7;

import java.util.Arrays;

public class ConsecutiveStrings {
    public static String longestConsec(String[] strarr, int k) {
        if (k == 0) {
            return "";
        }

        String[] subStrs = new String[strarr.length - k + 1];
        for (int i = 0; i < subStrs.length; i++) {
            subStrs[i] = Arrays.toString(Arrays.copyOfRange(strarr, i, i + k));
        }

        return Arrays.stream(subStrs).max(String::compareTo).get();
    }
}
